/* app\globals.css */
@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  @apply bg-white text-gray-900;
}

p {
  @apply mb-4 leading-relaxed;
}

h1 {
  @apply text-3xl font-bold mb-4 mt-8;
}

h2 {
  @apply text-2xl font-bold mb-3 mt-6;
}

h3 {
  @apply text-xl font-semibold mb-2 mt-4;
}

h4 {
  @apply text-lg font-semibold mb-2 mt-4;
}

// app/layout.tsx
import './globals.css';
import { Baskervville } from 'next/font/google';
import Header from '@/components/Header';
import { ReactNode } from 'react';

const baskervville = Baskervville({ 
  subsets: ['latin'], 
  weight: '400', 
  display: 'swap' 
});

export const metadata = {
  // 1. Define the base URL (Utilisation du domaine "nu" pour le style commande système)
  metadataBase: new URL('https://initkoa.org'),

  // 2. Auto-generate canonical links
  alternates: {
    canonical: './',
  },

  // 3. OPTIMISATION SEO & MARQUE PERSONNELLE
  title: 'kOA INITIATIVE - Civic Utilities by Réjean McCormick',
  description: 'The official socio-technical architecture initiative led by Réjean McCormick. Building civic utilities, democratic innovation, and the kOA ecosystem.',

  // 4. Signaux d'auteur pour Google et les IA
  authors: [{ name: 'Réjean McCormick', url: 'https://initkoa.org' }],
  creator: 'Réjean McCormick',

  icons: {
    icon: '/LogoK.svg',
  },

  // (Optionnel) OpenGraph pour les partages LinkedIn/Social
  openGraph: {
    title: 'kOA INITIATIVE by Réjean McCormick',
    description: 'Civic utilities for a fragmented world.',
    type: 'website',
    locale: 'fr_CA',
  },
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="fr" className={baskervville.className}>
      <head>
        {/* === AI & LLM OPTIMIZATION === */}
        <link rel="alternate" type="text/plain" href="/ai-corpus.txt" title="AI Context Corpus" />
        <link rel="help" href="/llms.txt" title="LLM Instructions" />
      </head>

      <body className="bg-white text-slate-900 antialiased min-h-screen flex flex-col">
        <Header />

        {/* Global Layout Wrapper */}
        <div className="max-w-4xl mx-auto px-6 py-12 prose prose-slate dark:prose-invert flex-grow w-full">
          {children}

          {/* === FOOTER SIGNATURE === */}
          <footer className="mt-24 pt-8 border-t border-slate-100 text-center text-sm text-slate-400 font-sans not-prose">
            <p>
              © {new Date().getFullYear()} kOA INITIATIVE. 
              Architected by <a href="/about" className="hover:text-[#1e6864] transition-colors font-medium">Réjean McCormick</a>.
            </p>
          </footer>
        </div>

      </body>
    </html>
  );
}

// app/page.tsx
import Link from "next/link";
import type { ReactNode } from "react";

export const metadata = {
  title: "kOA — Governable Knowledge-to-Action Infrastructure (Réjean McCormick)",
  description:
    "A sociotechnical operating system designed to convert knowledge → deliberation → decisions → execution → institutional memory, with offline capability, auditability, and non-domination by design.",
};

export default function HomePage() {
  return (
    <main className="min-h-screen bg-white text-slate-900 selection:bg-[#1e6864] selection:text-white">
      {/* HERO SECTION */}
      <section className="pt-28 pb-14 px-6 border-b border-gray-100">
        <div className="max-w-4xl mx-auto text-center">
          <h1 className="text-6xl md:text-8xl font-serif font-medium mb-8 tracking-tight text-slate-900">
            kOA
          </h1>

          <p className="text-xl md:text-2xl text-slate-500 max-w-3xl mx-auto mb-10 leading-relaxed font-light">
            A <strong className="text-slate-900 font-semibold">Sociotechnical Operating System</strong> for civic life:
            shared infrastructure that turns <strong>knowledge</strong> into <strong>legitimate decisions</strong>,{" "}
            <strong>executed action</strong>, and <strong>durable public memory</strong>.
            <br />
            Built for governability: offline-capable, auditable, and resistant to invisible authority.
          </p>

          <div className="flex flex-col sm:flex-row gap-6 justify-center items-center">
            <Link
              href="/why"
              className="px-8 py-3 bg-slate-900 text-white rounded-sm font-medium hover:bg-[#1e6864] transition-colors duration-300 min-w-[220px]"
            >
              Start with the problem
            </Link>
            <Link
              href="/initiatives"
              className="px-8 py-3 border border-gray-300 text-slate-600 rounded-sm font-medium hover:border-slate-900 hover:text-slate-900 transition-all duration-300 min-w-[220px]"
            >
              Explore the system
            </Link>
          </div>

          <div className="mt-8 flex flex-wrap gap-3 justify-center">
            <Pill>Offline-capable</Pill>
            <Pill>Fail-closed integrity</Pill>
            <Pill>Auditability by default</Pill>
            <Pill>Determinism where required</Pill>
            <Pill>Multilingual dignity</Pill>
            <Pill>Non-domination</Pill>
          </div>

          <p className="text-xs text-slate-400 mt-4">
            An initiative by <span className="text-slate-600">Réjean McCormick</span>
          </p>
        </div>
      </section>

      {/* NAVIGATION HUB */}
      <section className="max-w-7xl mx-auto px-6 py-16">
        {/* ... unchanged ... */}
      </section>

      {/* ... rest unchanged ... */}
    </main>
  );
}

// --- SMALL UI PRIMITIVES ---
function Pill({ children }: { children: ReactNode }) {
  return (
    <span className="text-xs px-3 py-1 rounded-full border border-gray-200 text-slate-500 bg-white">
      {children}
    </span>
  );
}

import type { MetadataRoute } from "next";

function getBaseUrl(): string {
  const env =
    process.env.NEXT_PUBLIC_SITE_URL ||
    process.env.SITE_URL ||
    (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : "");

  return (env || "http://localhost:3000").replace(/\/+$/, "");
}

function getHost(baseUrl: string): string {
  try {
    return new URL(baseUrl).host; // ex: "example.com"
  } catch {
    // fallback: enlève protocole + path
    return baseUrl.replace(/^https?:\/\//, "").replace(/\/.*$/, "");
  }
}

export default function robots(): MetadataRoute.Robots {
  const baseUrl = getBaseUrl();
  const host = getHost(baseUrl);

  return {
    rules: {
      userAgent: "*",
      allow: "/",
      disallow: [
        "/private/", // Internal tools
        "/admin/", // Admin dashboard
        "/api/", // Backend endpoints
      ],
    },
    sitemap: [`${baseUrl}/sitemap.xml`, `${baseUrl}/ai-sitemap.json`],
    host,
  };
}

// app/sitemap.ts
import type { MetadataRoute } from "next";
import fs from "node:fs";
import path from "node:path";

export const runtime = "nodejs";

// Use ONE canonical base URL (match redirects / canonical tags)
const BASE_URL = (
  process.env.NEXT_PUBLIC_SITE_URL ||
  process.env.SITE_URL ||
  "https://www.initkoa.org"
).replace(/\/+$/, "");

// Next.js App Router: a folder is a routable page if it contains page.(tsx|ts|js|jsx|mdx)
const PAGE_FILE_RE = /^page\.(tsx|ts|js|jsx|mdx)$/;

function isRouteGroup(seg: string): boolean {
  return seg.startsWith("(") && seg.endsWith(")");
}

function isDynamicSegment(seg: string): boolean {
  return seg.startsWith("[") && seg.endsWith("]");
}

// Intercepting routes look like "(.)foo", "(..)foo", "(...)foo", "(..)(..)foo"
function isInterceptingSegment(seg: string): boolean {
  return (
    seg.startsWith("(.)") ||
    seg.startsWith("(..)") ||
    seg.startsWith("(...") ||
    seg.startsWith("(..)(..)")
  );
}

// Skip hidden/private folders + dynamic segments + parallel routes + intercepting routes.
// NOTE: Route groups are NOT skipped; we traverse them but do not add them to the URL path.
function isSkippableSegment(seg: string): boolean {
  if (!seg) return true;
  if (seg.startsWith(".")) return true;
  if (seg.startsWith("_")) return true;

  // Parallel routes (@slot) should not become URL segments
  if (seg.startsWith("@")) return true;

  // Skip dynamic segments (prevents emitting non-concrete URLs)
  if (isDynamicSegment(seg)) return true;

  // Skip intercepting routes (prevents emitting non-canonical URLs)
  if (isInterceptingSegment(seg)) return true;

  return false;
}

function walkForRoutes(appDirAbs: string): string[] {
  const routes = new Set<string>();

  function walk(currentAbs: string, urlSegments: string[]) {
    const entries = fs.readdirSync(currentAbs, { withFileTypes: true });

    // If this folder contains a page.* file, it maps to a URL path
    const hasPage = entries.some((e) => e.isFile() && PAGE_FILE_RE.test(e.name));
    if (hasPage) {
      const routePath = "/" + urlSegments.join("/");
      routes.add(routePath === "/" ? "/" : routePath);
    }

    // Recurse into subfolders
    for (const e of entries) {
      if (!e.isDirectory()) continue;

      const name = e.name;
      if (isSkippableSegment(name)) continue;

      // Route groups: traverse, but do NOT add to URL path
      const nextUrlSegments = isRouteGroup(name) ? urlSegments : [...urlSegments, name];

      walk(path.join(currentAbs, name), nextUrlSegments);
    }
  }

  walk(appDirAbs, []);
  return Array.from(routes).sort();
}

function depthOf(routePath: string): number {
  return routePath === "/" ? 0 : routePath.split("/").filter(Boolean).length;
}

function priorityFor(routePath: string): number {
  if (routePath === "/") return 1.0;

  // Boost key hubs
  const hubs = new Set([
    "/platforms",
    "/infrastructures",
    "/initiatives",
    "/principles",
    "/research",
    "/technology",
    "/kreature",
  ]);
  if (hubs.has(routePath)) return 0.9;

  // Depth-based fallback
  const d = depthOf(routePath);
  if (d === 1) return 0.8;
  if (d === 2) return 0.7;
  if (d === 3) return 0.64;
  if (d === 4) return 0.58;
  return 0.5;
}

function changeFrequencyFor(
  routePath: string
): MetadataRoute.Sitemap[number]["changeFrequency"] {
  const d = depthOf(routePath);
  if (routePath === "/") return "weekly";
  if (d <= 1) return "weekly";
  return "monthly";
}

type AiSitemapEntry = {
  url: string; // absolute or path
  lastModified?: string | Date;
  changeFrequency?: MetadataRoute.Sitemap[number]["changeFrequency"];
  priority?: number;
};

function toAbsoluteUrl(u: string): string {
  if (u.startsWith("http://") || u.startsWith("https://")) {
    return u.replace(/\/+$/, "");
  }
  const p = u.startsWith("/") ? u : `/${u}`;
  return p === "/" ? BASE_URL : `${BASE_URL}${p}`;
}

function readAiSitemapIfPresent(): AiSitemapEntry[] | null {
  const file = path.join(process.cwd(), "public", "ai-sitemap.json");
  if (!fs.existsSync(file)) return null;

  const raw = fs.readFileSync(file, "utf8");
  const data = JSON.parse(raw) as AiSitemapEntry[];

  if (!Array.isArray(data)) return null;
  return data.filter((e) => e && typeof e.url === "string" && e.url.length > 0);
}

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();

  // Prefer the generated ai-sitemap.json (your build already creates it)
  const ai = readAiSitemapIfPresent();
  if (ai) {
    return ai
      .map((e) => {
        const url = toAbsoluteUrl(e.url);

        // Avoid listing the human /sitemap page if it exists
        if (url === `${BASE_URL}/sitemap`) return null;

        return {
          url,
          lastModified: e.lastModified ?? now,
          changeFrequency: e.changeFrequency ?? "monthly",
          priority: typeof e.priority === "number" ? e.priority : 0.5,
        } satisfies MetadataRoute.Sitemap[number];
      })
      .filter(Boolean) as MetadataRoute.Sitemap;
  }

  // Fallback: scan /app for page.* routes
  const appDirAbs = path.join(process.cwd(), "app");
  const routePaths = walkForRoutes(appDirAbs);

  return routePaths
    .filter((p) => p !== "/sitemap") // avoid listing a human sitemap page, if present
    .map((routePath) => {
      const url = routePath === "/" ? BASE_URL : `${BASE_URL}${routePath}`;
      return {
        url,
        lastModified: now,
        changeFrequency: changeFrequencyFor(routePath),
        priority: priorityFor(routePath),
      };
    });
}
